"""Proposte aggiunte per i confronti per tema (sanità, politica estera, immigrazione) e temi riassegnati.

Le voci segnate [verificare] sono dati o sviluppi da controllare su fonti ufficiali prima di pubblicarli.
Punteggi 1-5: vedi la pagina "Come giudichiamo" e analisi/dati_voti.py.
"""


def n(pdf, ordine, pagina, titolo, tema, voti, costo, motivazione, promessa, precedenti, fondi, rischi_benefici):
    f, c, s, ch, ri = voti
    return dict(pdf=pdf, ordine=ordine, pagina=pagina, titolo=titolo, tema=tema, voto_fattibilita=f,
                voto_copertura=c, voto_esiti=s, voto_chiarezza=ch, voto_rischi=ri, costo=costo,
                motivazione=motivazione, promessa=promessa, precedenti='\n'.join(precedenti), fondi=fondi,
                rischi_benefici='\n'.join(rischi_benefici))


